import 'database.dart';

// Note: this imports database.dart (not just tables.dart) because the
// Companion types below (CatalogEntriesCompanion, etc.) are generated by
// drift as part of database.dart's `@DriftDatabase`/`part` pair, not
// tables.dart itself. database.dart imports this file right back for
// [seedCatalog]/[seedShoppingList] — that's a legal import cycle in Dart
// (unlike `part`/`part of`), since neither side has a circular *value*
// dependency, only type dependencies.

/// Phase 1 seed product catalog (EQ-A2 in docs/test-plan.md).
///
/// A small, hand-picked dataset standing in for the real shared
/// barcode/nutrition databases (ADR 0012/ADR 0013), which arrive in a
/// later phase. Barcodes are fake products but *are* checksum-valid
/// UPC-A codes (not just arbitrary 12-digit strings) — Stage 2's barcode
/// image fixtures are generated from these same codes, and a real UPC-A
/// decoder (ML Kit included) validates the check digit, so an
/// invalid-checksum code simply wouldn't decode.
///
/// UREQS: SCAN-1, SYNC-1
final List<CatalogEntriesCompanion> seedCatalog = [
  _catalogEntry('100000000014', 'Whole Milk, 1 Gal', 'dairy'),
  _catalogEntry('100000000021', '2% Milk, 1 Gal', 'dairy'),
  _catalogEntry('100000000038', "Thomas's English Muffins", 'bakery'),
  _catalogEntry('100000000045', 'Panko Bread Crumbs', 'pantry'),
  _catalogEntry('100000000052', 'Creamy Peanut Butter', 'pantry'),
  _catalogEntry('100000000069', 'Sourdough Bread', 'bakery'),
  _catalogEntry('100000000076', 'Large Eggs, Dozen', 'dairy'),
  _catalogEntry('100000000083', 'Salted Butter', 'dairy'),
  _catalogEntry('100000000090', 'Roma Tomatoes', 'produce'),
  _catalogEntry('100000000106', 'Yellow Onion', 'produce'),
  _catalogEntry('100000000113', 'Ground Coffee, Medium Roast', 'pantry'),
  _catalogEntry('100000000120', 'Orange Juice, 64oz', 'beverages'),
];

CatalogEntriesCompanion _catalogEntry(
  String barcode,
  String name,
  String category,
) {
  return CatalogEntriesCompanion.insert(
    barcode: barcode,
    name: name,
    category: category,
  );
}

/// Phase 1 seed shopping list, deliberately covering every matching path
/// the engine (LIST-2/LIST-3/LIST-6) needs to handle. Product names here
/// are real items a tester is likely to actually have at home, so the
/// barcode fixtures in `app/test/fixtures/barcodes/` can be printed and
/// scanned against real products, not just the fixture images:
///
/// - "Milk" ties between two catalog entries → ambiguous match (LIST-3).
/// - "Thomas's English Mufins" (deliberate typo, missing one "f") still
///   confidently matches the catalog's "Thomas's English Muffins" — but
///   via ordinary Jaccard token overlap (3 of the item's 4 tokens are
///   still an exact match; only the misspelled word differs), not via
///   MatchingService's separate fuzzy/misspelling path. A single-word
///   typo is what actually isolates that fuzzy path — see
///   test/services/matching_service_test.dart's "Yogurt"/"Yogurrt" case —
///   since a multi-word phrase gets partial credit from its other shared
///   words before fuzzy scoring is even reached. This item is still a
///   useful real-world case on its own: manual entry not running through
///   the matching engine at all (not case-sensitivity) was the actual
///   Phase 1 bug this seed data was expanded to cover.
/// - "Panko Bread Crumbs" matches a catalog entry exactly (LIST-2).
/// - "Fresh Basil" has no catalog entry at all → can only ever be resolved
///   by manual add (LIST-5), demonstrating scanning isn't the only path.
///
/// UREQS: LIST-2, LIST-3, LIST-5, LIST-6, LSTORG-2, SYNC-1
List<ShoppingListItemsCompanion> seedShoppingListItems(int listId) => [
  _listItem(listId, 'Milk', 'dairy'),
  _listItem(listId, "Thomas's English Mufins", 'bakery'),
  _listItem(listId, 'Panko Bread Crumbs', 'pantry'),
  _listItem(listId, 'Fresh Basil', 'produce'),
];

ShoppingListItemsCompanion _listItem(
  int listId,
  String name,
  String category,
) {
  return ShoppingListItemsCompanion.insert(
    listId: listId,
    name: name,
    category: category,
    status: ListItemStatus.pending,
  );
}
